import sys,json,struct,os,collections
def scan(p):
    try:
        with open(p,'rb') as f:
            h=f.read(12)
            if h[:4]!=b'glTF': return None
            l,t=struct.unpack('<II',f.read(8))
            j=json.loads(f.read(l))
        anims=j.get('animations',[])
        return [a.get('name','') for a in anims]
    except Exception as e: return None
if __name__=='__main__':
    root=sys.argv[1]; res=collections.defaultdict(lambda:[0,0,0]); 
    out=[]
    for d,_,fs in os.walk(root):
        for fn in fs:
            if fn.lower().endswith('.glb'):
                p=os.path.join(d,fn); r=scan(p)
                key='/'.join(p.split('/')[:5])
                res[key][0]+=1
                if r is None: res[key][2]+=1
                elif r: res[key][1]+=1; res[key].append(len(r))
                if r: out.append((p,r))
    tot=[0,0,0,0]
    for k,v in sorted(res.items()):
        clips=sum(v[3:])
        if v[1]: print(k,'glbs',v[0],'animated',v[1],'clips',clips,'bad',v[2])
        tot[0]+=v[0];tot[1]+=v[1];tot[2]+=clips;tot[3]+=v[2]
    print('TOTAL glb',tot[0],'animated',tot[1],'clips',tot[2],'bad',tot[3])
    json.dump(out,open('/tank/cyrus-library-staging/motion/_animscan.json','w'))
