  source: z.string().max(40),
  pack: z.string().max(120).nullable(),
  /** path inside the staged/source library (never a customer path) */
  path: z.string().max(400).nullable(),
  retrievedAt: z.string().max(32).nullable(),
  /** upstream id / repo@sha the row came through */
  via: z.string().max(160).nullable(),
  /** content hashes this asset was derived from (a retexture lists its base) */
  derivedFrom: z.array(z.string().regex(SHA256_HEX)).max(16).default([]),
}).strict();

export const CatalogEntryV1Z = z.object({
  schemaVersion: z.literal(CATALOG_SCHEMA_VERSION),
  /** sha256 of the asset bytes (a texture set / HDRI: of its primary file); also the dedupe key */
  id: z.string().regex(SHA256_HEX),
  kind: z.enum(CATALOG_KINDS),
  title: z.string().trim().min(2).max(80),
  shortDescription: z.string().trim().min(10).max(140),
  /** controlled vocabulary (vocab.json tags / styles / object words) */
  tags: z.array(tag).max(16),
  /** anything else that looked useful, max 8 */
  freeTags: z.array(tag).max(8).default([]),
  categories: z.object({ primary: cat, secondary: z.array(cat).max(3).default([]) }).strict(),
  /** situation ids from vocab.json useFor */
  useFor: z.array(z.string().regex(/^[a-z0-9-]{2,48}$/)).max(8).default([]),
  style: z.string().max(24).nullable(),
  quality: QualityZ,
  /** game id -> fit, only for games with an AssetProfile; missing game = unknown (never assumed good) */
  games: z.record(z.string().regex(GAME_RE), GameFitZ).default({}),
  tech: TechZ,
  licence: LicenceZ,
  provenance: ProvenanceZ,
  legalClass: z.enum(LEGAL_CLASSES),
  /** opaque contributor id (never an email or a Nxeon user id); null for packs */
  contributedBy: z.string().regex(/^[a-z0-9_-]{4,64}$/).nullable().default(null),
  status: z.enum(CATALOG_STATUSES),
  /** why the status is what it is (content-filter flags, owner note) */
  statusReason: z.string().max(300).nullable().default(null),
  /** content-filter flag ids (lib/cyrus/library/v2/filters.ts) */
  flags: z.array(z.string().max(48)).max(12).default([]),
  /** near-duplicate / variant group: same stem + sizes in other colours or numbering */
  group: z.string().max(120).nullable().default(null),
  /** sha256 of a better copy when this one is a near-duplicate */
  duplicateOf: z.string().regex(SHA256_HEX).nullable().default(null),
  thumbnail: z.string().max(400).nullable().default(null),
  enrichment: z.object({
    by: z.enum(ENRICHED_BY),
    /** 0-1: how sure the stage was that title/category/useFor are right */
    confidence: z.number().min(0).max(1),
    /** full = stage A described it well enough to pick; partial = category only; none = needs stage B */
    coverage: z.enum(["full", "partial", "none"]),
    /** stage-b model id, when stage B ran */
    model: z.string().max(60).nullable().default(null),
    at: z.string().max(32),
    /** what stage A could not decide (feeds the stage-B queue and the owner review) */
    gaps: z.array(z.string().max(80)).max(8).default([]),
  }).strict(),
}).strict();

export type CatalogEntry = z.output<typeof CatalogEntryV1Z>;
export type CatalogEntryInput = z.input<typeof CatalogEntryV1Z>;
export type EntryIssue = { path: string; code: string; message: string };

/** Structured validation (never throws) + cross-field rules. */
export function validateCatalogEntry(raw: unknown): { ok: true; entry: CatalogEntry } | { ok: false; errors: EntryIssue[] } {
  const r = CatalogEntryV1Z.safeParse(raw);
  if (!r.success) return { ok: false, errors: r.error.issues.map((i) => ({ path: i.path.join(".") || "entry", code: "invalid", message: i.message })) };
  const e = r.data;
  const errors: EntryIssue[] = [];
  const add = (path: string, code: string, message: string) => errors.push({ path, code, message });
  if (e.categories.secondary.includes(e.categories.primary)) add("categories.secondary", "duplicate_primary", "a secondary category repeats the primary");
