# Deterministic .blend/.dae -> glb (best-of: NLA_TRACKS vs ACTIONS). Blender 5.2 headless in the sandbox.
import bpy, sys, os, json, glob
W = '/tank/nxeon-build/tmp/blender-poc/work'
IN = W + '/blend'; OUT = W + '/glb'
os.makedirs(OUT, exist_ok=True)
report = {}
def count_anims(p):
    import struct
    with open(p, 'rb') as f:
        f.read(12); l, t = struct.unpack('<II', f.read(8)); j = json.loads(f.read(l))
    return len(j.get('animations', []))
files = sorted(glob.glob(IN + '/*.blend')) + sorted(glob.glob(IN + '/*.dae'))
for f in files:
    base = os.path.splitext(os.path.basename(f))[0]
    try:
        if f.endswith('.blend'):
            bpy.ops.wm.open_mainfile(filepath=f)
        else:
            bpy.ops.wm.read_factory_settings(use_empty=True)
            bpy.ops.wm.collada_import(filepath=f)
    except Exception as e:
        report[base] = {'error': 'open:' + str(e)[:120]}; continue
    for a in bpy.data.actions: a.use_fake_user = True
    arms = [o for o in bpy.data.objects if o.type == 'ARMATURE']
    for arm in arms:
        bones = set(b.name for b in arm.pose.bones)
        ad = arm.animation_data or arm.animation_data_create()
        existing = set(t.name for t in ad.nla_tracks)
        for a in bpy.data.actions:
            ok = True; n = 0
            for fc in a.fcurves if hasattr(a, 'fcurves') else []:
                if fc.data_path.startswith('pose.bones['):
                    n += 1
                    nm = fc.data_path.split('"')[1] if '"' in fc.data_path else ''
                    if nm not in bones: ok = False; break
            if n and ok and a.name not in existing:
                tr = ad.nla_tracks.new(); tr.name = a.name
                try: tr.strips.new(a.name, int(a.frame_range[0]), a)
                except Exception: pass
    best = None
    for mode in ('NLA_TRACKS', 'ACTIONS'):
        out = os.path.join(OUT, f'{base}__{mode}.glb')
        try:
            bpy.ops.export_scene.gltf(filepath=out, export_format='GLB', export_animations=True, export_animation_mode=mode, export_apply=False, export_yup=True, export_force_sampling=True, export_optimize_animation_size=False)
            n = count_anims(out)
            if best is None or n > best[1]: best = (out, n)
        except Exception as e:
            report.setdefault(base, {})['err_' + mode] = str(e)[:100]
    if best:
        final = os.path.join(OUT, base + '.glb')
        os.replace(best[0], final)
        for mode in ('NLA_TRACKS', 'ACTIONS'):
            p = os.path.join(OUT, f'{base}__{mode}.glb')
            if os.path.exists(p): os.remove(p)
        report.setdefault(base, {}).update({'ok': True, 'animations': best[1], 'actions': len(bpy.data.actions), 'armatures': len(arms)})
json.dump(report, open(OUT + '/_blendreport.json', 'w'), indent=1)
print('DONE', len(files))
E
